import styled from "styled-components";

export const AboutContainer = styled.div`
    width: 90%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    @media screen and (min-width: 1024px){
        flex-direction: row-reverse;

      
    }
    


`

export const ImageWrapper = styled.div`
    width: 100%;
    heigth:8rem;
    display: flex;
    align-items: center;
    justify-content: center;


    img{
        width: 100%;
        height: 100%;
    }

    @media screen and (min-width: 1024px){
        
    img{
        width: 70%;
       
    }

      
    }

  

`

export const TextWrapper = styled.div`
    width: 95%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    h2{
        text-align: center;
        font-size:1.2rem;
        font-weight: 600;
        font-family:"Raleway", sans serif;
    }
    P{
        font-family:"Raleway", sans serif;
        color: #6C7D89;
        text-align: center;
        font-weight: 400;
        font-size: 0.8rem;
        margin-top:1rem;
    }

    ul{
      
        list-style: none;
        margin-top:1rem;
     
        
    }
    ul>li{
        
        font-family:"Raleway", sans serif;
        display: flex;
        align-items: center;
        margin-bottom: .5rem;

    }
    @media screen and (min-width: 1024px){

        ul{
           
            display: flex;
            flex-wrap: wrap;
            justify-content:space-around;
           
            
        }
        ul>li{
            width:50%;
        }

      
    }
`
export const ButtonContainer = styled.div`
    width: 70%;
    
    
    
    p{
        color:#3D723D;
        font-family:"Raleway", sans serif;
        font-size: 1rem;
        font-weight:500;
        text-align:left;
        margin-bottom:0;
    }

    @media screen and (min-width: 1024px){
        
        width: 100%;
        margin-left:3rem;

        button{
            width:35%;
            border: 1px solid #136657;
        }
      
    }
    

    `
